// ==========================================================================
// ZenGarden::PlantPottedDrawHeightOffset(SeedType,float)
// @0019DCC8  342 bytes
// ==========================================================================
float ZenGarden::PlantPottedDrawHeightOffset(SeedType theSeedType, float theScale)
{
  if ( theSeedType == 11 )
    return (float)((float)(theScale * 15.0) - 15.0) + 50.0;
  if ( theSeedType == 8 )
    return (float)((float)(theScale * 24.0) - 24.0) + 10.0;
  if ( theSeedType != 9 )
  {
    switch ( theSeedType )
    {
      case 0xDu:
        return (float)((float)(theScale * 5.0) - 5.0) + 5.0;
      case 0x13u:
        return (float)((float)(theScale * 20.0) - 20.0) - 18.0;
      case 0x18u:
        return (float)((float)(theScale * 15.0) - 15.0) - 20.0;
      case 0x10u:
        return (float)((float)(theScale * 30.0) - 30.0) - 10.0;
      case 6u:
        return 0.0;
      default:
        break;
    }
    if ( theSeedType == 12 || theSeedType == 31 || theSeedType <= 1 )
      return (float)(theScale * 10.0) - 10.0;
    bool aLowOffset = (theSeedType & 0xFFFFFFFD) == 5 || theSeedType == 53;
    if ( aLowOffset || theSeedType == 18 || theSeedType == 38 )
      return (float)(theScale * 10.0) - 10.0;
    if ( theSeedType != 29 )
    {
      if ( theSeedType == 32 || theSeedType == 39 )
        return (float)((float)(theScale * 10.0) - 10.0) + 3.0;
      switch ( theSeedType )
      {
        case 4u:
          return (float)(theScale * 5.0) - 5.0;
        case 0x16u:
          return (float)(theScale * 3.0) - 3.0;
        case 0x15u:
          return (float)((float)(theScale * 10.0) - 10.0) - 13.0;
        default:
          break;
      }
      if ( theSeedType != 27 )
      {
        if ( theSeedType == 30 )
          return (float)(theScale * 20.0) - 20.0;
        if ( theSeedType == 25 )
          return 1.0 - theScale;
        return 0.0;
      }
      return (float)(theScale * 10.0) - 10.0;
    }
    return (float)((float)(theScale * 24.0) - 24.0) + 10.0;
  }
  return (float)((float)(theScale * 17.0) - 17.0) + 10.0;
}

